package com.nm.fragmentsclean.adminImportContext.adapters.secondary.gateways.editorial;
import com.nm.fragmentsclean.adminImportContext.businessLogic.ports.TopicCandidateDecisionPort; import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.usecases.DecideTopicCandidate; import java.util.UUID;
public final class TopicCandidateDecisionAdapter implements TopicCandidateDecisionPort {private final DecideTopicCandidate decisions;public TopicCandidateDecisionAdapter(DecideTopicCandidate decisions){this.decisions=decisions;}public void decide(UUID id,String decision){switch(decision){case "RETAIN"->decisions.retain(id);case "DEFER"->decisions.defer(id);case "IGNORE"->decisions.ignore(id);default->throw new IllegalArgumentException("Unknown topic candidate decision");}}}
